    z = Complex.ofCartesian(0, -1);
    Assert.assertEquals(-Math.PI / 2, z.getArgument(), 1.0e-12);
    z = Complex.ofCartesian(1, -1);
    Assert.assertEquals(-Math.PI / 4, z.getArgument(), 1.0e-12);
}

